void WebContentsImpl::AttachInterstitialPage(
    InterstitialPageImpl* interstitial_page) {
  DCHECK(interstitial_page);
  if (!interstitial_page)
    return;
  GetRenderManager()->set_interstitial_page(interstitial_page);

  CancelActiveAndPendingDialogs();

  for (auto& observer : observers_)
    observer.DidAttachInterstitialPage();

  if (frame_tree_.IsLoading())
    LoadingStateChanged(true, true, nullptr);

  if (node_.OuterContentsFrameTreeNode()) {
    if (GetRenderManager()->GetProxyToOuterDelegate()) {
      RenderWidgetHostView* view = interstitial_page->GetView();
      DCHECK(view);
      if (!view)
        return;
      DCHECK(static_cast<RenderWidgetHostViewBase*>(view)
                 ->IsRenderWidgetHostViewChildFrame());
      if (!static_cast<RenderWidgetHostViewBase*>(view)
               ->IsRenderWidgetHostViewChildFrame())
        return;
      RenderWidgetHostViewChildFrame* child_view =
          static_cast<RenderWidgetHostViewChildFrame*>(view);
      GetRenderManager()->SetRWHViewForInnerContents(child_view);
    }
  }
}

