            DEBUGMSGTL(("mibindex", "add: index %d too large\n", i ));
            return -1;
        }
        new_indexes = realloc(_mibindexes,
                              new_max * sizeof(_mibindexes[0]));
        if ( !new_indexes ) {
            DEBUGMSGTL(("mibindex", "add: realloc failed\n"));
            return -1;
        }
        _mibindexes = new_indexes;
        _mibindex_max = new_max;
        memset(_mibindexes + old_mibindex_max, 0,
