    if ( _mibindexes[i] )
        free(_mibindexes[i]);
    _mibindexes[ i ] = strdup( dirname );
    if ( !_mibindexes[i] ) {
        DEBUGMSGTL(("mibindex", "add: strdup failed\n"));
        return -1;
    }
    if ( i >= _mibindex )
        _mibindex = i+1;

    DEBUGMSGTL(("mibindex", "add: %d/%d/%d\n", i, _mibindex, _mibindex_max ));
    return i;
}

