	/* bits needs to be a multiple of 8 */
	if (bits & 0x07)
		return -EINVAL;

	while (*str) {
		sign = *str++;
		if (sign != '+' && sign != '-')
			return -EINVAL;
		tmp = simple_strtoul(str, &np, 0);
		if (str == np || tmp >= (unsigned long)bits)
			return -EINVAL;
		a = (int)tmp;
		z = a;
		str = np;
		if (*str == '-') {
			tmp = simple_strtoul(++str, &np, 0);
			if (str == np || tmp < (unsigned long)a || tmp >= (unsigned long)bits)
				return -EINVAL;
			z = (int)tmp;
			str = np;
		}
		for (i = a; i <= z; i++)
			if (sign == '+')
				set_bit_inv(i, bitmap);
			else
				clear_bit_inv(i, bitmap);
		while (*str == ',' || *str == '\n')
			str++;
	}

	return 0;
}

